output_text:
[
  {
    "id": "borrow_entrance_cart",
    "text": "A shopper must take the entrance cart before proceeding with the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "carrying_cart": "hasCart"
      },
      "events": {
        "borrow_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "carrying_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "borrow_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Items should not be picked up by hand; item pickup is permitted only while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_cart": "hasCart",
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "carrying_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_nw_bay",
    "text": "Before leaving the store, the shopper must return the cart to the northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_bay": "at(0,1)",
        "cart_returned_to_bay": "cartAt(0,1)",
        "carrying_cart": "hasCart"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "nw_cart_return_bay",
              "carrying_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_to_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "drop_cart_only_at_return_bay",
    "text": "A cart may be put down only at the northwest cart-return bay.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_bay": "at(0,1)"
      },
      "events": {
        "drop_cart_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "nw_cart_return_bay"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "drop_cart_outside_return_bay"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "The shopper must not exit while still holding the cart or while the cart is not parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_bay": "cartAt(0,1)",
        "cart_unreturned": {
          "or": [
            "hasCart",
            {
              "not": "cart_returned_to_bay"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_unreturned"
        ]
      }
    }
  },
  {
    "id": "do_not_push_cart_past_return_bay",
    "text": "Once the shopper reaches the northwest return bay with the cart, they must leave it there rather than push it onward.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return_bay": "at(0,1)",
        "carrying_cart": "hasCart"
      },
      "events": {
        "push_cart_away_from_return_bay": {
          "pre": {
            "and": [
              "nw_cart_return_bay",
              "carrying_cart",
              "MOVE"
            ]
          },
          "post": {
            "not": "nw_cart_return_bay"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_away_from_return_bay"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "After the cart has been returned, the shopper should not resume shopping or perform further object interactions.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_bay": "cartAt(0,1)",
        "shopper_without_cart_after_return": {
          "and": [
            "cart_returned_to_bay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "shopper_without_cart_after_return",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "after_return_move_only_toward_exit",
    "text": "After returning the cart, the shopper should proceed toward the east exit and not move north or west.",
    "abstraction": {
      "state_properties": {
        "cart_returned_to_bay": "cartAt(0,1)",
        "shopper_without_cart_after_return": {
          "and": [
            "cart_returned_to_bay",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_wrong_way_move": {
          "pre": {
            "and": [
              "shopper_without_cart_after_return",
              {
                "or": [
                  "N",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_wrong_way_move"
    }
  }
]
